"""Join WAF access, ModSecurity audit and application records into observations.

Identity rules (see docs/ARCHITECTURE_DECISIONS.md ADR-007):
* ``client_ip`` is taken from the WAF access record (its TCP peer), never from
  forwarded headers or from the application.
* The request id is generated by the WAF; app/audit records that reference an
  id the WAF never logged are orphans and are counted, not trusted.
"""

from __future__ import annotations

import hashlib
import time
from collections import OrderedDict
from dataclasses import dataclass, field
from datetime import datetime

from afw.domain.common import new_id
from afw.domain.events import HttpObservation, IdsAlert, Provenance
from afw.telemetry.parsers.records import AppRecord, SuricataAlert, WafAccess, WafAudit
from afw.telemetry.routes import RouteMatcher
from afw.telemetry.stats import TelemetryStats

SCHEMA_VERSION = 2  # telemetry envelope: content ids for IDS, receipt time (M5)


@dataclass
class _Pending:
    first_seen: float
    access: WafAccess | None = None
    audit: WafAudit | None = None
    app: AppRecord | None = None


@dataclass
class RequestCorrelator:
    default_app: str
    matchers: dict[str, RouteMatcher]
    stats: TelemetryStats
    join_wait_s: float = 1.0
    max_pending: int = 5000
    _pending: OrderedDict[str, _Pending] = field(default_factory=OrderedDict)
    _emitted: OrderedDict[str, None] = field(default_factory=OrderedDict)
    _emitted_cap: int = 50_000

    def _slot(self, rid: str, now: float) -> _Pending | None:
        if rid in self._emitted:
            self.stats.inc("duplicate")
            return None
        slot = self._pending.get(rid)
        if slot is None:
            if len(self._pending) >= self.max_pending:
                _, dropped = self._pending.popitem(last=False)
                self.stats.inc("join_overflow")
                del dropped
            slot = _Pending(first_seen=now)
            self._pending[rid] = slot
        return slot

    def add_access(self, rec: WafAccess, now: float | None = None) -> None:
        slot = self._slot(rec.request_id, time.monotonic() if now is None else now)
        if slot is not None:
            if slot.access is not None:
                self.stats.inc("duplicate")
            slot.access = rec

    def add_audit(self, rec: WafAudit, now: float | None = None) -> None:
        slot = self._slot(rec.request_id, time.monotonic() if now is None else now)
        if slot is not None:
            slot.audit = rec

    def add_app(self, rec: AppRecord, now: float | None = None) -> None:
        slot = self._slot(rec.request_id, time.monotonic() if now is None else now)
        if slot is not None:
            slot.app = rec

    def flush(self, now: float | None = None, force: bool = False) -> list[HttpObservation]:
        now = time.monotonic() if now is None else now
        out: list[HttpObservation] = []
        for rid in list(self._pending):
            slot = self._pending[rid]
            complete = slot.access is not None and slot.app is not None and slot.audit is not None
            if not (complete or force or now - slot.first_seen >= self.join_wait_s):
                continue
            del self._pending[rid]
            if slot.access is None:
                self.stats.inc("orphan_app" if slot.app else "orphan_audit")
                continue
            out.append(self._build(slot.access, slot.audit, slot.app))
            self._emitted[rid] = None
            if len(self._emitted) > self._emitted_cap:
                self._emitted.popitem(last=False)
        self.stats.inc("observations", len(out))
        return out

    def _build(
        self, access: WafAccess, audit: WafAudit | None, app: AppRecord | None
    ) -> HttpObservation:
        if audit is not None and audit.client_ip != access.client_ip:
            self.stats.inc("audit_ip_mismatch")
        app_id = app.app_id if app else (access.app_id or self.default_app)
        matcher = self.matchers.get(app_id)
        route = (
            app.route
            if app and app.route and not app.route.startswith("<")
            else (matcher.match(access.path) if matcher else access.path[:128])
        )
        reached = app is not None or (access.upstream_status is not None)
        # ADR-029: authenticated only if every contributing record came over an
        # authenticated sensor channel and the application confirmed the request.
        authenticated = (
            access.authenticated
            and app is not None
            and app.authenticated
            and (audit is None or audit.authenticated)
        )
        return HttpObservation(
            event_id=new_id("obs"),
            request_id=access.request_id,
            app_id=app_id,
            observed_at=access.observed_at,
            client_ip=access.client_ip,
            method=access.method,
            path=access.path[:256],
            route=route,
            status=access.status,
            bytes_in=access.bytes_in,
            bytes_out=access.bytes_out,
            duration_ms=access.duration_ms,
            user_agent_hash=access.user_agent_hash,
            waf_rule_ids=audit.rule_ids if audit else (),
            waf_anomaly_score=audit.anomaly_score if audit else 0,
            waf_blocked=bool(audit and audit.blocked) or (access.status == 403 and not reached),
            app_joined=app is not None,
            auth_outcome=app.auth_outcome if app else None,
            username_hash=app.username_hash if app else None,
            app_version=app.app_version if app else None,
            reached_backend=reached,
            provenance=Provenance.AUTHENTICATED if authenticated else Provenance.UNVERIFIED,
            schema_version=SCHEMA_VERSION,
            received_at=access.received_at,
        )

    @property
    def pending(self) -> int:
        return len(self._pending)


def to_ids_alert(rec: SuricataAlert, received_at: datetime | None = None) -> IdsAlert:
    """Content-derived id: the same Suricata alert line always yields the same id."""
    key = "|".join(
        str(x)
        for x in (
            rec.sensor_id,
            rec.flow_id,
            rec.observed_at.isoformat(),
            rec.signature_id,
            rec.src_ip,
            rec.dst_ip,
            rec.dst_port,
            rec.proto,
        )
    )
    return IdsAlert(
        event_id="ids-" + hashlib.sha256(key.encode()).hexdigest()[:32],
        schema_version=SCHEMA_VERSION,
        received_at=received_at,
        **rec.model_dump(),
    )
